#include <bits/stdc++.h>
using namespace std;static constexpr uint32_t P=1000000007u;
static uint32_t pw(uint32_t a,uint32_t e){uint64_t r=1,x=a;while(e){if(e&1)r=r*x%P;x=x*x%P;e>>=1;}return r;}
static int code(string_view s){int x=0;for(char c:s)x=x*3+(c=='N'?0:c=='R'?1:2);return x;}
static int prefh(string_view s){int h=1;for(char c:s){if(c=='R')--h;else if(c=='L')++h;}return h;}
static int rankRows(vector<unordered_map<int,uint32_t>>& rows){unordered_map<int,unordered_map<int,uint32_t>> basis;int rank=0;for(auto &rr:rows){auto r=move(rr);while(!r.empty()){int j=INT_MAX;for(auto const&kv:r)if(kv.second&&kv.first<j)j=kv.first;if(j==INT_MAX)break;auto it=basis.find(j);if(it==basis.end()){uint32_t inv=pw(r[j],P-2);for(auto &kv:r)kv.second=(uint64_t)kv.second*inv%P;basis.emplace(j,move(r));++rank;break;}uint32_t a=r[j];for(auto const&kv:it->second){uint32_t sub=(uint64_t)a*kv.second%P;auto jt=r.find(kv.first);uint32_t old=jt==r.end()?0:jt->second;uint32_t nv=old>=sub?old-sub:old+P-sub;if(nv)r[kv.first]=nv;else if(jt!=r.end())r.erase(jt);}}}return rank;}
int main(int argc,char**argv){string path=argv[1];int W=atoi(argv[2]),K=atoi(argv[3]);int NR=1,NC=1;for(int i=0;i<K;++i)NR*=3;for(int i=K;i<W;++i)NC*=3;vector<vector<unordered_map<int,uint32_t>>> by(W+2);for(auto&v:by)v.resize(NR);ifstream f(path);int w;string s;uint32_t x;while(f>>w>>s>>x){if(w!=W||!x)continue;auto p=string_view(s).substr(0,K);int h=prefh(p);if(h<0||h>(int)W+1)continue;by[h][code(p)][code(string_view(s).substr(K))]=x;}int sum=0;for(int h=0;h<=W+1;++h){int nrows=0,nz=0;for(auto const&r:by[h])if(!r.empty()){++nrows;nz+=r.size();}if(!nrows)continue;int r=rankRows(by[h]);cout<<"h="<<h<<" rows="<<nrows<<" nz="<<nz<<" rank="<<r<<"\n";sum+=r;}cout<<"sum="<<sum<<"\n";}
